from pathlib import Path
import subprocess
ROOT = Path.cwd()
head = subprocess.check_output(['git','rev-parse','--short','HEAD'], text=True).strip()
if not head.startswith('97909ca'): raise SystemExit(f'Expected HEAD 97909ca, found {head}. Stop and have ChatGPT re-inspect.')
def read(rel): return (ROOT / rel).read_text(encoding='utf-8')
def write(rel, content):
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding='utf-8')
def repl(text, old, new, label):
    count = text.count(old)
    if count != 1: raise SystemExit(f'{label}: expected 1 match, found {count}')
    return text.replace(old, new, 1)
write('app/(portal)/cosmetics/page.tsx', 'import { redirect } from "next/navigation";\n\nimport {\n  PlayerCosmeticsManager,\n  type PlayerCosmeticRow,\n} from "@/components/cosmetics/player-cosmetics-manager";\nimport { createClient } from "@/lib/supabase/server";\n\nexport const dynamic = "force-dynamic";\nexport const revalidate = 0;\n\nexport default async function CosmeticsPage() {\n  const supabase = await createClient();\n\n  const { data: { user } } = await supabase.auth.getUser();\n  if (!user) redirect("/login");\n\n  const { data: character, error: characterError } = await supabase\n    .from("characters")\n    .select("id")\n    .eq("user_id", user.id)\n    .maybeSingle();\n\n  if (characterError || !character) redirect("/");\n\n  const [entitlementResult, preferenceResult] = await Promise.all([\n    supabase\n      .from("character_cosmetic_entitlements")\n      .select(`\n        cosmetic_item_id,\n        cosmetic:cosmetic_items!character_cosmetic_entitlements_cosmetic_item_id_fkey(\n          id, slug, name, description, category, preview_image_url, asset_url, sort_order, is_active\n        )\n      `)\n      .eq("character_id", character.id)\n      .eq("enabled", true),\n\n    supabase\n      .from("character_cosmetic_preferences")\n      .select("equipped_sheet_frame_id, equipped_chat_frame_id")\n      .eq("character_id", character.id)\n      .maybeSingle(),\n  ]);\n\n  const firstError = entitlementResult.error ?? preferenceResult.error;\n  if (firstError) throw new Error(`Unable to load Cosmetics: ${firstError.message}`);\n\n  const cosmetics: PlayerCosmeticRow[] = (entitlementResult.data ?? [])\n    .map((entry) => {\n      const relation = Array.isArray(entry.cosmetic) ? entry.cosmetic[0] : entry.cosmetic;\n      if (!relation || relation.is_active !== true) return null;\n      if (relation.category !== "sheet_frame" && relation.category !== "chat_frame") return null;\n      return {\n        id: String(relation.id),\n        slug: String(relation.slug),\n        name: String(relation.name),\n        description: relation.description ?? "",\n        category: relation.category,\n        previewImageUrl: relation.preview_image_url ?? null,\n        assetUrl: relation.asset_url ?? null,\n        sortOrder: Number(relation.sort_order ?? 0),\n      };\n    })\n    .filter((entry): entry is PlayerCosmeticRow => entry !== null)\n    .sort((a, b) => a.sortOrder - b.sortOrder || a.name.localeCompare(b.name));\n\n  return (\n    <main className="p-5 sm:p-7 lg:p-9">\n      <div className="mx-auto max-w-7xl">\n        <p className="text-[9px] uppercase tracking-[0.28em] text-[rgb(var(--sep-colour-8c704b))]">Premium</p>\n        <h1 className="mt-2 font-serif text-4xl text-[rgb(var(--sep-colour-ead5ac))]">Cosmetics</h1>\n        <p className="mt-3 max-w-3xl text-sm leading-7 text-[rgb(var(--sep-colour-a99b89))]">\n          Choose the visual treatments your character currently wears. You can own many cosmetics, but only one cosmetic can be equipped in each slot at a time.\n        </p>\n\n        <PlayerCosmeticsManager\n          initialCosmetics={cosmetics}\n          initialSheetFrameId={preferenceResult.data?.equipped_sheet_frame_id ?? null}\n          initialChatFrameId={preferenceResult.data?.equipped_chat_frame_id ?? null}\n        />\n      </div>\n    </main>\n  );\n}\n')
write('app/(portal)/cosmetics/actions.ts', '"use server";\n\nimport { revalidatePath } from "next/cache";\nimport { createAdminClient } from "@/lib/supabase/admin";\nimport { createClient } from "@/lib/supabase/server";\n\ntype CosmeticSlot = "sheet_frame" | "chat_frame";\n\nfunction readSlot(value: FormDataEntryValue | null): CosmeticSlot {\n  if (value === "sheet_frame" || value === "chat_frame") return value;\n  throw new Error("Invalid cosmetic slot.");\n}\n\nexport async function setEquippedCosmetic(formData: FormData) {\n  const supabase = await createClient();\n  const { data: { user } } = await supabase.auth.getUser();\n  if (!user) throw new Error("You must be signed in.");\n\n  const { data: character, error: characterError } = await supabase\n    .from("characters")\n    .select("id")\n    .eq("user_id", user.id)\n    .maybeSingle();\n\n  if (characterError || !character) {\n    throw new Error(characterError?.message ?? "Character not found.");\n  }\n\n  const slot = readSlot(formData.get("slot"));\n  const cosmeticIdRaw = String(formData.get("cosmeticId") ?? "").trim();\n  const cosmeticId = cosmeticIdRaw || null;\n  const admin = createAdminClient();\n\n  if (cosmeticId) {\n    const [cosmeticResult, entitlementResult] = await Promise.all([\n      admin\n        .from("cosmetic_items")\n        .select("id, category, is_active")\n        .eq("id", cosmeticId)\n        .maybeSingle(),\n      admin\n        .from("character_cosmetic_entitlements")\n        .select("enabled")\n        .eq("character_id", character.id)\n        .eq("cosmetic_item_id", cosmeticId)\n        .maybeSingle(),\n    ]);\n\n    if (cosmeticResult.error || !cosmeticResult.data) {\n      throw new Error(cosmeticResult.error?.message ?? "Cosmetic not found.");\n    }\n\n    if (cosmeticResult.data.is_active !== true) {\n      throw new Error("Inactive cosmetics cannot be equipped.");\n    }\n\n    if (cosmeticResult.data.category !== slot) {\n      throw new Error("That cosmetic does not belong in this slot.");\n    }\n\n    if (entitlementResult.error || entitlementResult.data?.enabled !== true) {\n      throw new Error(entitlementResult.error?.message ?? "You do not own that cosmetic.");\n    }\n  }\n\n  const column = slot === "sheet_frame" ? "equipped_sheet_frame_id" : "equipped_chat_frame_id";\n\n  const { error: preferenceError } = await admin\n    .from("character_cosmetic_preferences")\n    .upsert(\n      {\n        character_id: character.id,\n        [column]: cosmeticId,\n        updated_at: new Date().toISOString(),\n      },\n      { onConflict: "character_id" },\n    );\n\n  if (preferenceError) {\n    throw new Error(`Unable to equip cosmetic: ${preferenceError.message}`);\n  }\n\n  revalidatePath("/cosmetics");\n  revalidatePath("/character");\n  revalidatePath("/characters");\n  revalidatePath("/game");\n  revalidatePath("/", "layout");\n}\n')
write('components/cosmetics/player-cosmetics-manager.tsx', '"use client";\n\nimport { useState, useTransition } from "react";\nimport { setEquippedCosmetic } from "@/app/(portal)/cosmetics/actions";\n\nexport type PlayerCosmeticRow = {\n  id: string;\n  slug: string;\n  name: string;\n  description: string;\n  category: "sheet_frame" | "chat_frame";\n  previewImageUrl: string | null;\n  assetUrl: string | null;\n  sortOrder: number;\n};\n\ntype Tab = "sheet_frame" | "chat_frame";\n\nfunction tabLabel(tab: Tab) {\n  return tab === "sheet_frame" ? "Sheet Frames" : "Chat Frames";\n}\n\nexport function PlayerCosmeticsManager({\n  initialCosmetics,\n  initialSheetFrameId,\n  initialChatFrameId,\n}: {\n  initialCosmetics: PlayerCosmeticRow[];\n  initialSheetFrameId: string | null;\n  initialChatFrameId: string | null;\n}) {\n  const [tab, setTab] = useState<Tab>("sheet_frame");\n  const [sheetFrameId, setSheetFrameId] = useState(initialSheetFrameId);\n  const [chatFrameId, setChatFrameId] = useState(initialChatFrameId);\n  const [message, setMessage] = useState("");\n  const [failed, setFailed] = useState(false);\n  const [pending, startTransition] = useTransition();\n\n  const visible = initialCosmetics.filter((item) => item.category === tab);\n  const equippedId = tab === "sheet_frame" ? sheetFrameId : chatFrameId;\n\n  function changeEquipped(cosmeticId: string | null) {\n    setMessage("");\n    setFailed(false);\n    const data = new FormData();\n    data.set("slot", tab);\n    data.set("cosmeticId", cosmeticId ?? "");\n\n    startTransition(async () => {\n      try {\n        await setEquippedCosmetic(data);\n        if (tab === "sheet_frame") setSheetFrameId(cosmeticId);\n        else setChatFrameId(cosmeticId);\n        setMessage(cosmeticId ? "Cosmetic equipped." : "Cosmetic unequipped.");\n      } catch (error) {\n        setFailed(true);\n        setMessage(error instanceof Error ? error.message : "Unable to update cosmetic.");\n      }\n    });\n  }\n\n  return (\n    <section className="mt-7 overflow-hidden border border-[rgb(var(--sep-colour-60482e))]/45 bg-[rgb(var(--sep-colour-15100d))]">\n      <header className="border-b border-[rgb(var(--sep-colour-60482e))]/35 bg-[rgb(var(--sep-colour-100c09))] px-5 py-4">\n        <p className="text-[8px] uppercase tracking-[0.22em] text-[rgb(var(--sep-colour-a68152))]">Your collection</p>\n        <h2 className="mt-1 font-serif text-2xl text-[rgb(var(--sep-colour-dfc99f))]">Equipped Appearance</h2>\n        <p className="mt-2 text-[11px] leading-5 text-[rgb(var(--sep-colour-8f8271))]">Cosmetics are visual only and never change gameplay.</p>\n      </header>\n\n      <div className="flex border-b border-[rgb(var(--sep-colour-60482e))]/35">\n        {(["sheet_frame", "chat_frame"] as const).map((value) => (\n          <button\n            key={value}\n            type="button"\n            onClick={() => { setTab(value); setMessage(""); }}\n            className={[\n              "flex-1 px-4 py-3 text-[9px] uppercase tracking-[0.18em] transition",\n              tab === value\n                ? "bg-[rgb(var(--sep-colour-332719))] text-[rgb(var(--sep-colour-efd9aa))]"\n                : "bg-[rgb(var(--sep-colour-120d0a))] text-[rgb(var(--sep-colour-8f806c))] hover:text-[rgb(var(--sep-colour-cbb28a))]",\n            ].join(" ")}\n          >\n            {tabLabel(value)}\n          </button>\n        ))}\n      </div>\n\n      {message ? (\n        <div className={[\n          "mx-5 mt-5 border px-4 py-3 text-xs",\n          failed ? "border-red-800/55 text-red-200" : "border-[rgb(var(--sep-colour-56754f))]/55 text-[rgb(var(--sep-colour-c5d7bd))]",\n        ].join(" ")}>\n          {message}\n        </div>\n      ) : null}\n\n      <div className="p-5">\n        {equippedId ? (\n          <div className="mb-5 flex flex-wrap items-center justify-between gap-3 border border-[rgb(var(--sep-colour-765937))]/45 bg-[rgb(var(--sep-colour-21170f))] px-4 py-3">\n            <div>\n              <p className="text-[8px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-8c704b))]">Current</p>\n              <p className="mt-1 font-serif text-lg text-[rgb(var(--sep-colour-dfc99f))]">\n                {initialCosmetics.find((item) => item.id === equippedId)?.name ?? "Equipped cosmetic"}\n              </p>\n            </div>\n            <button\n              type="button"\n              disabled={pending}\n              onClick={() => changeEquipped(null)}\n              className="border border-[rgb(var(--sep-colour-765937))]/55 px-4 py-2 text-[8px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-cbb28a))] disabled:opacity-45"\n            >\n              Unequip\n            </button>\n          </div>\n        ) : null}\n\n        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">\n          {visible.map((item) => {\n            const equipped = item.id === equippedId;\n            return (\n              <article key={item.id} className={[\n                "overflow-hidden border bg-[rgb(var(--sep-colour-100c09))]",\n                equipped ? "border-[rgb(var(--sep-colour-987344))]" : "border-[rgb(var(--sep-colour-59432c))]/45",\n              ].join(" ")}>\n                <div className="flex h-44 items-center justify-center bg-[rgb(var(--sep-colour-0d0a08))] p-4">\n                  {item.previewImageUrl ?? item.assetUrl ? (\n                    <img src={item.previewImageUrl ?? item.assetUrl ?? ""} alt="" className="max-h-full max-w-full object-contain" />\n                  ) : (\n                    <span className="text-[8px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-625747))]">No preview</span>\n                  )}\n                </div>\n                <div className="p-4">\n                  <p className="text-[7px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-806b50))]">\n                    {tab === "sheet_frame" ? "Sheet Frame" : "Location Chat Frame"}\n                  </p>\n                  <h3 className="mt-1 font-serif text-xl text-[rgb(var(--sep-colour-dfc99f))]">{item.name}</h3>\n                  <p className="mt-2 min-h-10 text-[10px] leading-5 text-[rgb(var(--sep-colour-8f8271))]">\n                    {item.description || "Collectible Sepulchria cosmetic."}\n                  </p>\n                  <button\n                    type="button"\n                    disabled={pending || equipped}\n                    onClick={() => changeEquipped(item.id)}\n                    className="mt-4 w-full border border-[rgb(var(--sep-colour-987344))] bg-[rgb(var(--sep-colour-3b2919))] px-4 py-2.5 text-[8px] uppercase tracking-[0.16em] text-[rgb(var(--sep-colour-efd6a8))] disabled:opacity-45"\n                  >\n                    {equipped ? "Equipped" : pending ? "Working..." : "Equip"}\n                  </button>\n                </div>\n              </article>\n            );\n          })}\n        </div>\n\n        {visible.length === 0 ? (\n          <div className="border border-dashed border-[rgb(var(--sep-colour-59432c))]/40 px-5 py-10 text-center">\n            <p className="font-serif text-lg text-[rgb(var(--sep-colour-bba17a))]">No {tabLabel(tab).toLowerCase()} owned yet.</p>\n            <p className="mt-2 text-[10px] leading-5 text-[rgb(var(--sep-colour-706452))]">Cosmetics unlocked later will appear here automatically.</p>\n          </div>\n        ) : null}\n      </div>\n    </section>\n  );\n}\n')
