rel='components/portal/portal-sidebar.tsx'; text=read(rel); text=repl(text, 'const friendsItem: NavigationItem = {\n  label: "Friend List",', 'const cosmeticsItem: NavigationItem = {\n  label: "Cosmetics",\n  title:\n    "Manage your owned character and chat cosmetics.",\n  icon: "/icons/premium.png",\n  href: "/cosmetics",\n  activePaths: ["/cosmetics"],\n};\n\nconst friendsItem: NavigationItem = {\n  label: "Friend List",', 'cosmetics nav item')
text=repl(text, '  const [\n    hasPrivateLocationAccess,\n    setHasPrivateLocationAccess,\n  ] = useState(false);\n\n  const refreshPrivateLocationAccess =', '  const [\n    hasPrivateLocationAccess,\n    setHasPrivateLocationAccess,\n  ] = useState(false);\n\n  const [\n    hasCosmetics,\n    setHasCosmetics,\n  ] = useState(false);\n\n  const refreshCosmeticsAccess =\n    useCallback(async () => {\n      const supabase = createClient();\n      const { data: { user } } = await supabase.auth.getUser();\n\n      if (!user) {\n        setHasCosmetics(false);\n        return;\n      }\n\n      const { data: character } = await supabase\n        .from("characters")\n        .select("id")\n        .eq("user_id", user.id)\n        .maybeSingle();\n\n      if (!character) {\n        setHasCosmetics(false);\n        return;\n      }\n\n      const { data, error } = await supabase\n        .from("character_cosmetic_entitlements")\n        .select("cosmetic_item_id")\n        .eq("character_id", character.id)\n        .eq("enabled", true)\n        .limit(1);\n\n      if (error) {\n        console.error("Unable to check Cosmetic access:", error);\n        setHasCosmetics(false);\n        return;\n      }\n\n      setHasCosmetics((data ?? []).length > 0);\n    }, []);\n\n  const refreshPrivateLocationAccess =', 'cosmetics access state')
text=repl(text, '  useEffect(() => {\n    void refreshPrivateLocationAccess();', '  useEffect(() => {\n    void refreshCosmeticsAccess();\n\n    function handleFocus() {\n      void refreshCosmeticsAccess();\n    }\n\n    function handleVisibility() {\n      if (document.visibilityState === "visible") {\n        void refreshCosmeticsAccess();\n      }\n    }\n\n    window.addEventListener("focus", handleFocus);\n    document.addEventListener("visibilitychange", handleVisibility);\n\n    return () => {\n      window.removeEventListener("focus", handleFocus);\n      document.removeEventListener("visibilitychange", handleVisibility);\n    };\n  }, [refreshCosmeticsAccess]);\n\n  useEffect(() => {\n    void refreshPrivateLocationAccess();', 'cosmetics refresh effect')
